// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    Succeeder callee;

    function setUp() public {
        c = new Proxy();
        callee = new Succeeder();
    }

    function testFuzz_property(address actor, bytes calldata data) public {
        vm.assume(actor != address(0));
        vm.prank(actor);
        bool ok;
        try c.forward(address(callee), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok, "forward must succeed when the callee succeeds");
    }
}

contract Succeeder {
    fallback() external payable {}
}
